const SKY_LIST=Object.entries(SKY).map(([a,n])=>[norm(a).trim(),n]).sort((a,b)=>b[0].length-a[0].length);
const skyIn=t=>{ for(const [a,n] of SKY_LIST) if(t.includes(' '+a+' ')) return n; return null; };

